import{g as o,ad as t,r as a,A as r}from"./chunks/framework.CK2aBVEu.js";const m=JSON.parse('{"title":"Legacy components","description":"","frontmatter":{},"headers":[],"relativePath":"docs/components/legacy.md","filePath":"docs/components/legacy.md","lastUpdated":1786525954000}'),d={name:"docs/components/legacy.md"};function c(i,e,n,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="legacy-components" tabindex="-1">Legacy components <a class="header-anchor" href="#legacy-components" aria-label="Permalink to “Legacy components”">​</a></h1><p>Two different things happened to the v0 library. They need different work from you, so check which one applies before you start.</p><table tabindex="0"><thead><tr><th>State</th><th>Import path</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Removed</strong></td><td>none — the import fails</td><td>Rewrite the call site against the replacement</td></tr><tr><td><strong>Parked</strong></td><td><code>frappe-ui/experimental</code></td><td>Change the import path, then plan the move</td></tr></tbody></table><p>A removed component is gone for good and has a named replacement. A parked component still ships and still works: it moved to the <a href="/docs/experimental"><code>frappe-ui/experimental</code></a> subpath while its future is decided, and it can come back to the root export or be deleted in any release. Parked components are exempt from the deprecation policy, so treat the import-path change as a stopgap, not a destination.</p><h2 id="removed-in-v1" tabindex="-1">Removed in v1 <a class="header-anchor" href="#removed-in-v1" aria-label="Permalink to “Removed in v1”">​</a></h2><p>These are no longer in the library. The import fails at build time unless the entry says otherwise. Most have a before/after in the <a href="./../migration">migration guide</a>; the rest are in the <a href="./../changelog">changelog</a>.</p><ul><li><strong><code>Input</code></strong> — use <a href="./textinput"><code>TextInput</code></a> for text-like inputs (<code>text</code>, <code>number</code>, <code>email</code>, <code>password</code>, <code>date</code>), <a href="./textarea"><code>Textarea</code></a>, <a href="./select"><code>Select</code></a>, and <a href="./checkbox"><code>Checkbox</code></a> for the other type modes the original <code>Input</code> accepted. <code>TextInput</code> and friends share a labeling contract (<code>label</code>, <code>description</code>, <code>error</code>, <code>required</code>) and a sized/variant API that <code>Input</code> never had.</li><li><strong><code>Autocomplete</code></strong> — use <a href="./combobox"><code>Combobox</code></a> for single-select and <a href="./multiselect"><code>MultiSelect</code></a> for multi-select. Both use the shared input primitives, render the same label/description/error contract as the rest of the v1 input family, and have a smaller, more predictable API surface.</li><li><strong><code>FormControl type=&quot;autocomplete&quot;</code></strong> — use <code>type=&quot;combobox&quot;</code>, or a standalone <a href="./combobox"><code>Combobox</code></a>, which exposes the full set of slots and props without the wrapper layer. Removing this one is <strong>silent</strong>: the type falls through to a plain text input rather than failing.</li><li><strong><code>MonthPicker</code></strong> — use <a href="./select"><code>Select</code></a> with month options. It duplicated <code>Select</code> for a narrower case.</li><li><strong><code>CircularProgressBar</code></strong> — use <a href="./progress"><code>Progress</code></a>, or copy the old SFC into your app if you need the radial form. It was a second component for <code>Progress</code>&#39;s concept, with hardcoded light-mode colors.</li><li><strong><code>FeatherIcon</code></strong> — use a <code>lucide-*</code> icon class, or pass a component. See <a href="./../other/icons">Icons</a> for the icon-class system.</li><li><strong><code>NestedPopover</code></strong> — use <a href="./popover"><code>Popover</code></a>. It never nested anything.</li><li><strong><code>Card</code>, <code>ListItem</code>, standalone <code>&lt;Toast&gt;</code></strong> — three unmaintained wrappers. <code>Card</code> and <code>ListItem</code> have no drop-in replacement; rebuild the layout with plain markup (the migration guide has the before/after). For <code>&lt;Toast&gt;</code>, call the imperative <a href="./toast"><code>toast</code></a> API, which is unchanged.</li><li><strong><code>ListFilter</code></strong> — build filter UI in app code with <a href="./select"><code>Select</code></a> and <a href="./combobox"><code>Combobox</code></a>.</li><li><strong><code>GridLayout</code></strong> — depend on <code>grid-layout-plus</code> directly. It was a thin passthrough with no docs page and no tests.</li></ul><h2 id="parked-in-frappe-ui-experimental" tabindex="-1">Parked in <code>frappe-ui/experimental</code> <a class="header-anchor" href="#parked-in-frappe-ui-experimental" aria-label="Permalink to “Parked in frappe-ui/experimental”">​</a></h2><p>These still work. They left the root export, so the import path changes, and they carry no stability promise while they sit there. The <a href="/docs/experimental">Experimental overview</a> states what each one is waiting on.</p><ul><li><strong><code>ListView</code></strong> and its row/column parts — import from <a href="/docs/experimental#listview"><code>frappe-ui/experimental</code></a>. <a href="./../molecules/list"><code>frappe-ui/list</code></a> is the replacement for new code, but it has no equivalent for ListView&#39;s config-driven columns yet, so ListView stays parked until it does. Page: <a href="./../experimental/listview">ListView</a>.</li><li><strong><code>Calendar</code></strong> — import from <a href="/docs/experimental#calendar"><code>frappe-ui/experimental</code></a>. The public API is unchanged; it stays parked until a redesigned calendar family replaces it. Page: <a href="./../experimental/calendar">Calendar</a>.</li><li><strong><code>TextEditor</code>, <code>TextEditorBubbleMenu</code>, <code>TextEditorFixedMenu</code>, <code>TextEditorFloatingMenu</code>, <code>TextEditorContent</code>, <code>createEditorButton</code></strong> — import from <a href="/docs/experimental#texteditor-v0"><code>frappe-ui/experimental</code></a>. <a href="./../molecules/editor"><code>Editor</code></a> and its building blocks from the <code>frappe-ui/editor</code> subpath are the replacement; see the <a href="./../migration#editor">Editor migration section</a> for the full before/after.</li><li><strong><code>AxisChart</code>, <code>DonutChart</code>, <code>FunnelChart</code>, <code>NumberChart</code>, <code>ECharts</code>, <code>useAxisChartOptions</code></strong> — import from <a href="/docs/experimental#charts-v1"><code>frappe-ui/experimental</code></a>. <a href="./../charts/overview"><code>frappe-ui/charts</code></a> is the replacement family and draws everything these did.</li><li><strong><code>Icon</code>, <code>IconPicker</code>, <code>spritePlugin</code></strong> (the sprite icon trio) — import from <a href="/docs/experimental#sprite-icons"><code>frappe-ui/experimental</code></a>. <code>lucide-*</code> classes and the root <a href="./icon"><code>Icon</code></a> component are the canonical way to render icons, so this trio will be removed.</li></ul>',10)])])}const f=o(d,[["render",c]]);export{m as __pageData,f as default};
